-- DEC-047: availability counts when assigning educators to sections. The demonstration declared the same placeholder
-- slots for everyone (Monday 08:00-12:00 and Wednesday 14:00-17:00), unrelated to their classes; each educator gets
-- slots that cover the sections they teach, except one Saturday class of Tomás Aguilar, so the warning can be seen.
-- Only the untouched placeholder is replaced: availability that someone already edited stays as it is.
UPDATE staff_profiles SET availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":2,"start":"10:30","end":"12:00"},{"day":2,"start":"16:30","end":"19:00"},{"day":3,"start":"08:00","end":"12:00"},{"day":4,"start":"10:30","end":"12:00"},{"day":4,"start":"16:30","end":"19:00"},{"day":5,"start":"09:00","end":"11:00"},{"day":6,"start":"08:30","end":"10:30"}]' WHERE user_id='seed-user-ana' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
UPDATE staff_profiles SET availability='[{"day":1,"start":"07:30","end":"14:30"},{"day":2,"start":"09:30","end":"11:00"},{"day":3,"start":"07:30","end":"09:00"},{"day":4,"start":"09:30","end":"14:30"}]' WHERE user_id='seed-user-carlos' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
UPDATE staff_profiles SET availability='[{"day":1,"start":"07:30","end":"14:00"},{"day":2,"start":"09:30","end":"11:00"},{"day":3,"start":"07:30","end":"09:00"},{"day":4,"start":"09:30","end":"14:00"}]' WHERE user_id='seed-user-lucia' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
UPDATE staff_profiles SET availability='[{"day":2,"start":"14:00","end":"17:00"},{"day":4,"start":"14:00","end":"17:00"}]' WHERE user_id='seed-user-diego' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
UPDATE staff_profiles SET availability='[{"day":1,"start":"09:00","end":"11:00"},{"day":3,"start":"09:00","end":"11:00"},{"day":5,"start":"09:00","end":"11:00"},{"day":6,"start":"08:30","end":"10:30"}]' WHERE user_id='seed-user-sofia' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
UPDATE staff_profiles SET availability='[{"day":1,"start":"07:30","end":"09:30"},{"day":2,"start":"16:30","end":"19:00"},{"day":3,"start":"07:30","end":"09:30"},{"day":4,"start":"16:30","end":"19:00"},{"day":6,"start":"08:30","end":"11:15"}]' WHERE user_id='seed-user-tomas' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
UPDATE staff_profiles SET availability='[{"day":2,"start":"10:00","end":"13:00"},{"day":4,"start":"10:00","end":"13:00"}]' WHERE user_id='user-educator' AND organization_id='org-demo' AND availability='[{"day":1,"start":"08:00","end":"12:00"},{"day":3,"start":"14:00","end":"17:00"}]';
